-- Forward-only, additive. Existing rows remain private until explicitly published.
begin;
create extension if not exists postgis;
create extension if not exists pgcrypto;
-- Keep the SECURITY DEFINER search path unavailable for client-created objects.
revoke create on schema public from public, anon, authenticated;
create schema if not exists agriclimax_private;
revoke all on schema agriclimax_private from public, anon, authenticated;
grant usage on schema agriclimax_private to service_role;

create table agriclimax_private.indicators (
  id text primary key,
  unit text not null,
  metadata jsonb not null default '{}',
  created_at timestamptz not null default now()
);
create table agriclimax_private.parameter_versions (
  id text not null,
  version text not null,
  parameters jsonb not null check (jsonb_typeof(parameters) = 'object'),
  scientific_status text not null check (scientific_status in
    ('exploratory','documented','expert_reviewed','validated','deprecated')),
  provenance jsonb not null check (jsonb_typeof(provenance) = 'array'),
  created_at timestamptz not null default now(),
  primary key (id, version)
);
create table agriclimax_private.rule_versions (
  id text not null,
  version text not null,
  indicator_id text not null references agriclimax_private.indicators(id),
  parameter_id text not null,
  parameter_version text not null,
  metadata jsonb not null default '{}',
  created_at timestamptz not null default now(),
  primary key (id, version),
  foreign key (parameter_id, parameter_version)
    references agriclimax_private.parameter_versions(id, version)
);
create table agriclimax_private.run_manifests (
  id uuid primary key default gen_random_uuid(),
  idempotency_key text not null unique,
  status text not null check (status in ('processing','succeeded','failed')),
  engine_version text not null,
  started_at timestamptz not null default now(),
  completed_at timestamptz,
  provenance jsonb not null check (jsonb_typeof(provenance) = 'array'),
  quality jsonb not null check (jsonb_typeof(quality) = 'object'),
  manifest jsonb not null default '{}',
  check (completed_at is null or completed_at >= started_at)
);
create table agriclimax_private.observations (
  id uuid primary key default gen_random_uuid(),
  cell_id text not null references public.grid_cells(id),
  source_id text not null references public.sources(id),
  variable_id text not null,
  observed_at timestamptz not null,
  retrieved_at timestamptz not null,
  value double precision,
  unit text not null,
  quality jsonb not null check (jsonb_typeof(quality) = 'object'),
  run_id uuid not null references agriclimax_private.run_manifests(id),
  unique (cell_id, source_id, variable_id, observed_at, run_id)
);
create table agriclimax_private.indicator_results (
  id uuid primary key default gen_random_uuid(),
  cell_id text not null references public.grid_cells(id),
  valid_date date not null,
  production_id text not null references public.productions(id),
  indicator_id text not null references agriclimax_private.indicators(id),
  rule_id text not null,
  rule_version text not null,
  value double precision,
  unit text not null,
  provenance jsonb not null check (jsonb_typeof(provenance) = 'array'),
  quality jsonb not null check (jsonb_typeof(quality) = 'object'),
  run_id uuid not null references agriclimax_private.run_manifests(id),
  foreign key (rule_id, rule_version) references agriclimax_private.rule_versions(id, version),
  unique (cell_id, valid_date, production_id, indicator_id, rule_id, rule_version, run_id)
);
alter table public.risk_results
  add column published boolean not null default false,
  add column run_id uuid references agriclimax_private.run_manifests(id);

-- Publication requires contract-shaped essential fields. Full JSON Schema validation
-- remains an ingestion responsibility; these checks do not certify scientific validity.
alter table public.risk_results add constraint risk_results_publication_shape check (
  not published or coalesce(
    isfinite(valid_date)
    and jsonb_typeof(hazard) = 'object' and hazard ?& array['value','unit']
    and jsonb_typeof(hazard->'value') in ('number','null')
    and jsonb_typeof(hazard->'unit') = 'string'
    and jsonb_typeof(risk) = 'object'
    and risk - array['level','score'] = '{}'::jsonb
    and (not risk ? 'score' or jsonb_typeof(risk->'score') in ('number','null'))
    and risk->>'level' in ('low','moderate','high','critical','unavailable')
    and jsonb_typeof(confidence) = 'object'
    and confidence - array['level','scientific_status','reasons'] = '{}'::jsonb
    and (not confidence ? 'reasons' or (jsonb_typeof(confidence->'reasons') = 'array'
      and not jsonb_path_exists(confidence, '$.reasons[*] ? (@.type() != "string")')))
    and confidence->>'level' in ('low','medium','high')
    and confidence->>'scientific_status' in
      ('exploratory','documented','expert_reviewed','validated','deprecated')
    and jsonb_typeof(provenance) = 'array'
    and case when jsonb_typeof(provenance) = 'array' then jsonb_array_length(provenance) > 0 else false end
    and not jsonb_path_exists(provenance,
      '$[*] ? (@.type() != "object" || !exists(@.source_id) || @.source_id.type() != "string" || (exists(@.observed_at) && @.observed_at.type() != "string" && @.observed_at.type() != "null") || (exists(@.retrieved_at) && @.retrieved_at.type() != "string" && @.retrieved_at.type() != "null"))')
    and (exposure is null or jsonb_typeof(exposure) in ('object','null'))
    and (sensitivity is null or jsonb_typeof(sensitivity) in ('object','null'))
    and jsonb_typeof(quality) = 'object'
    and quality->>'freshness' in ('fresh','stale','unknown')
    and jsonb_typeof(quality->'flags') = 'array'
    and not jsonb_path_exists(quality, '$.flags[*] ? (@.type() != "string")'), false)
);

create index observations_cell_time_idx on agriclimax_private.observations
  (cell_id, variable_id, observed_at desc);
create index observations_run_idx on agriclimax_private.observations(run_id);
create index observations_source_time_idx on agriclimax_private.observations
  (source_id, variable_id, observed_at desc);
create index indicator_results_lookup_idx on agriclimax_private.indicator_results
  (production_id, indicator_id, valid_date, cell_id);
create index indicator_results_run_idx on agriclimax_private.indicator_results(run_id);
create index run_manifests_started_idx on agriclimax_private.run_manifests(started_at);
create index risk_results_published_map_idx on public.risk_results
  (production_id, indicator_id, rule_id, rule_version, valid_date, cell_id)
  where published;
create index risk_results_published_series_idx on public.risk_results
  (cell_id, production_id, indicator_id, rule_id, rule_version, valid_date)
  where published;
create index risk_results_run_idx on public.risk_results(run_id);

-- Reader is neither table owner nor BYPASSRLS. Only fixed, bounded RPCs use it.
create role agriclimax_api_reader nologin noinherit nobypassrls;
-- The migration executor must be able to transfer ownership of the fixed RPCs.
do $$ begin
  execute format('grant agriclimax_api_reader to %I', current_user);
  if exists(select 1 from pg_namespace where nspname = 'extensions') then
    revoke create on schema extensions from public, anon, authenticated;
    grant usage on schema extensions to agriclimax_api_reader;
  end if;
end $$;
grant usage on schema public to agriclimax_api_reader;
grant select on public.grid_cells, public.risk_results to agriclimax_api_reader;

do $$
declare t regclass;
begin
  foreach t in array array[
    'public.sources'::regclass, 'public.productions'::regclass,
    'public.grid_cells'::regclass, 'public.risk_results'::regclass,
    'public.watch_signals'::regclass,
    'agriclimax_private.indicators'::regclass,
    'agriclimax_private.parameter_versions'::regclass,
    'agriclimax_private.rule_versions'::regclass,
    'agriclimax_private.run_manifests'::regclass,
    'agriclimax_private.observations'::regclass,
    'agriclimax_private.indicator_results'::regclass
  ] loop
    execute format('alter table %s enable row level security', t);
    execute format('alter table %s force row level security', t);
    execute format('revoke all on table %s from public, anon, authenticated', t);
    execute format('grant select, insert, update, delete on table %s to service_role', t);
    execute format('create policy agriclimax_server on %s for all to service_role using (true) with check (true)', t);
  end loop;
end $$;
-- Versioned scientific metadata is append-only for ingestion. Operational manifests
-- and unpublished results can be corrected by the server; clients have no grants.
revoke update, delete on agriclimax_private.parameter_versions,
  agriclimax_private.rule_versions from service_role;
create policy agriclimax_map_geometry on public.grid_cells
  for select to agriclimax_api_reader using (true);
create policy agriclimax_published_results on public.risk_results
  for select to agriclimax_api_reader using (published);

-- Future private tables/functions remain closed by default (migration-owner scope).
alter default privileges in schema agriclimax_private revoke all on tables from public, anon, authenticated;
alter default privileges in schema agriclimax_private revoke execute on functions from public, anon, authenticated;
commit;

begin;

create function public.agriclimax_validate_query(
  p_production text, p_indicator text, p_rule text, p_version text,
  p_start date, p_end date, p_bbox double precision[] default null
) returns void language plpgsql immutable set search_path = pg_catalog as $$
begin
  if p_production is null or p_indicator is null or p_rule is null or p_version is null
    or p_production !~ '^[A-Za-z0-9_.-]{1,100}$'
    or p_indicator !~ '^[A-Za-z0-9_.-]{1,100}$'
    or p_rule !~ '^[A-Za-z0-9_.-]{1,100}$'
    or p_version !~ '^[A-Za-z0-9_.-]{1,100}$'
    or p_start is null or p_end is null or not isfinite(p_start) or not isfinite(p_end)
    or p_end < p_start or p_end - p_start > 365 then
    raise exception using errcode = '22023', message = 'Invalid query';
  end if;
  if p_bbox is not null and (
    array_ndims(p_bbox) is distinct from 1 or array_lower(p_bbox, 1) is distinct from 1
    or cardinality(p_bbox) <> 4 or array_position(p_bbox, null) is not null
    or not (p_bbox[1] >= -180 and p_bbox[3] <= 180
      and p_bbox[2] >= -90 and p_bbox[4] <= 90
      and p_bbox[1] < p_bbox[3] and p_bbox[2] < p_bbox[4])
  ) then
    raise exception using errcode = '22023', message = 'Invalid bbox';
  end if;
end $$;

create function public.agriclimax_risk_payload(r public.risk_results)
returns jsonb language sql immutable set search_path = pg_catalog as $$
  select jsonb_build_object(
    'schema_version', '1.0', 'cell_id', r.cell_id, 'valid_date', r.valid_date,
    'production_id', r.production_id, 'indicator_id', r.indicator_id,
    'hazard', r.hazard, 'exposure', r.exposure, 'sensitivity', r.sensitivity,
    'risk', r.risk, 'confidence', r.confidence,
    'rule', jsonb_build_object('rule_id', r.rule_id, 'version', r.rule_version),
    'provenance', r.provenance, 'quality', r.quality
  );
$$;

create function public.agriclimax_map_risks(
  p_production text, p_indicator text, p_rule text, p_version text,
  p_date date, p_bbox double precision[], p_zoom integer default 6,
  p_limit integer default 1000
) returns jsonb language plpgsql stable security definer
set search_path = pg_catalog, extensions, public set statement_timeout = '5s' as $$
declare result jsonb;
begin
  perform public.agriclimax_validate_query(p_production, p_indicator, p_rule, p_version, p_date, p_date, p_bbox);
  if p_bbox is null or p_zoom is null or p_zoom not between 0 and 22
    or p_limit is null or p_limit not between 1 and 2000 then
    raise exception using errcode = '22023', message = 'Invalid map bounds';
  end if;
  with bounded as materialized (
    select r, g.geom
    from public.grid_cells g join public.risk_results r on r.cell_id = g.id
    where r.published and r.production_id = p_production and r.indicator_id = p_indicator
      and r.rule_id = p_rule and r.rule_version = p_version and r.valid_date = p_date
      and g.geom && st_makeenvelope(p_bbox[1], p_bbox[2], p_bbox[3], p_bbox[4], 4326)
      and st_intersects(g.geom, st_makeenvelope(p_bbox[1], p_bbox[2], p_bbox[3], p_bbox[4], 4326))
    order by r.cell_id limit p_limit + 1
  ), page as (select * from bounded limit p_limit)
  select jsonb_build_object('type', 'FeatureCollection',
    'features', coalesce((select jsonb_agg(jsonb_build_object(
      'type', 'Feature', 'id', (r).id,
      'geometry', st_asgeojson(st_simplifypreservetopology(geom, 360.0 / (256 * power(2.0, p_zoom))))::jsonb,
      'properties', jsonb_build_object(
        'cell_id', (r).cell_id, 'valid_date', (r).valid_date,
        'production_id', (r).production_id, 'indicator_id', (r).indicator_id,
        'risk_level', (r).risk->>'level', 'confidence_level', (r).confidence->>'level',
        'freshness', (r).quality->>'freshness', 'hazard_value', (r).hazard->'value',
        'hazard_unit', (r).hazard->>'unit',
        'result', public.agriclimax_risk_payload(r)
      )
    ) order by (r).cell_id) from page), '[]'::jsonb),
    'truncated', (select count(*) > p_limit from bounded), 'limit', p_limit)
  into result;
  return result;
end $$;

create function public.agriclimax_risk_series(
  p_production text, p_indicator text, p_rule text, p_version text,
  p_cell text, p_start date, p_end date
) returns jsonb language plpgsql stable security definer
set search_path = pg_catalog, public set statement_timeout = '5s' as $$
begin
  perform public.agriclimax_validate_query(p_production, p_indicator, p_rule, p_version, p_start, p_end);
  if p_cell is null or p_cell !~ '^[A-Za-z0-9_.-]{1,100}$' then
    raise exception using errcode = '22023', message = 'Invalid cell';
  end if;
  return (select coalesce(jsonb_agg(public.agriclimax_risk_payload(r) order by r.valid_date), '[]'::jsonb)
    from public.risk_results r where r.published and r.cell_id = p_cell
      and r.production_id = p_production and r.indicator_id = p_indicator
      and r.rule_id = p_rule and r.rule_version = p_version
      and r.valid_date between p_start and p_end);
end $$;

-- Territory is an explicit bbox over existing grid cells, not a new business entity.
-- Counts describe intersecting cells, never a computed territory risk or area weighting.
create function public.agriclimax_territory_risks(
  p_production text, p_indicator text, p_rule text, p_version text,
  p_start date, p_end date, p_bbox double precision[]
) returns jsonb language plpgsql stable security definer
set search_path = pg_catalog, extensions, public set statement_timeout = '5s' as $$
begin
  perform public.agriclimax_validate_query(p_production, p_indicator, p_rule, p_version, p_start, p_end, p_bbox);
  if p_bbox is null then
    raise exception using errcode = '22023', message = 'Missing bbox';
  end if;
  return (with counts as (
    select r.valid_date, r.risk->>'level' as risk_level,
      r.confidence->>'level' as confidence_level, r.quality->>'freshness' as freshness,
      count(*) as cell_count, max(r.computed_at) as latest_computed_at
    from public.risk_results r join public.grid_cells g on g.id = r.cell_id
    where r.published and r.production_id = p_production and r.indicator_id = p_indicator
      and r.rule_id = p_rule and r.rule_version = p_version
      and r.valid_date between p_start and p_end
      and g.geom && st_makeenvelope(p_bbox[1], p_bbox[2], p_bbox[3], p_bbox[4], 4326)
      and st_intersects(g.geom, st_makeenvelope(p_bbox[1], p_bbox[2], p_bbox[3], p_bbox[4], 4326))
    group by r.valid_date, r.risk->>'level', r.confidence->>'level', r.quality->>'freshness'
  ) select jsonb_build_object('production_id', p_production, 'indicator_id', p_indicator,
    'rule', jsonb_build_object('rule_id', p_rule, 'version', p_version),
    'bbox', to_jsonb(p_bbox), 'aggregation', 'intersecting_cell_counts',
    'groups', coalesce(jsonb_agg(to_jsonb(counts) order by valid_date, risk_level, confidence_level, freshness), '[]'::jsonb)) from counts);
end $$;

-- No default PUBLIC execution, including helper functions.
revoke all on function public.agriclimax_validate_query(text,text,text,text,date,date,double precision[]) from public, anon, authenticated;
revoke all on function public.agriclimax_risk_payload(public.risk_results) from public, anon, authenticated;
grant execute on function public.agriclimax_validate_query(text,text,text,text,date,date,double precision[]),
  public.agriclimax_risk_payload(public.risk_results) to agriclimax_api_reader;

-- Temporary CREATE is needed solely to transfer function ownership; then removed.
grant create on schema public to agriclimax_api_reader;
alter function public.agriclimax_map_risks(text,text,text,text,date,double precision[],integer,integer) owner to agriclimax_api_reader;
alter function public.agriclimax_risk_series(text,text,text,text,text,date,date) owner to agriclimax_api_reader;
alter function public.agriclimax_territory_risks(text,text,text,text,date,date,double precision[]) owner to agriclimax_api_reader;
revoke create on schema public from agriclimax_api_reader;
revoke all on function public.agriclimax_map_risks(text,text,text,text,date,double precision[],integer,integer),
  public.agriclimax_risk_series(text,text,text,text,text,date,date),
  public.agriclimax_territory_risks(text,text,text,text,date,date,double precision[]) from public, anon, authenticated;
grant execute on function public.agriclimax_map_risks(text,text,text,text,date,double precision[],integer,integer),
  public.agriclimax_risk_series(text,text,text,text,text,date,date),
  public.agriclimax_territory_risks(text,text,text,text,date,date,double precision[]) to anon, authenticated, service_role;
notify pgrst, 'reload schema';
commit;

-- Additive station persistence. No polygon, interpolation, risk or scientific rule.
begin;
set local search_path = public, extensions;
create table agriclimax_private.weather_stations (
  id text primary key check (id ~ '^[0-9]{8}$'),
  name text not null,
  geom geometry(Point,4326) not null,
  altitude_m double precision not null,
  metadata jsonb not null check (jsonb_typeof(metadata) = 'object'),
  retrieved_at timestamptz not null
);
create table agriclimax_private.station_weather_batches (
  station_id text not null references agriclimax_private.weather_stations(id),
  source_id text not null references public.sources(id),
  valid_date date not null,
  payload jsonb not null check (jsonb_typeof(payload) = 'object'),
  retrieved_at timestamptz not null,
  run_id uuid not null references agriclimax_private.run_manifests(id),
  primary key (station_id,source_id,valid_date)
);
create index station_weather_batches_run_idx
  on agriclimax_private.station_weather_batches(run_id);

alter table agriclimax_private.weather_stations enable row level security;
alter table agriclimax_private.weather_stations force row level security;
alter table agriclimax_private.station_weather_batches enable row level security;
alter table agriclimax_private.station_weather_batches force row level security;
revoke all on agriclimax_private.weather_stations,
  agriclimax_private.station_weather_batches from public,anon,authenticated;
grant select,insert,update on agriclimax_private.weather_stations,
  agriclimax_private.station_weather_batches to service_role;
create policy agriclimax_station_server on agriclimax_private.weather_stations
  for all to service_role using (true) with check (true);
create policy agriclimax_station_batch_server on agriclimax_private.station_weather_batches
  for all to service_role using (true) with check (true);

create function public.agriclimax_persist_station_batch(
  p_batch jsonb, p_stations jsonb, p_idempotency_key text
) returns boolean language plpgsql security invoker
set search_path = pg_catalog, public, extensions
set statement_timeout = '10s'
as $$
declare
  v_run uuid;
  v_source text := p_batch->>'source_id';
  v_date date := (p_batch->>'valid_date')::date;
  v_retrieved timestamptz := (p_batch#>>'{provenance,retrieved_at}')::timestamptz;
  v_station jsonb;
  v_rows jsonb;
  v_payload jsonb;
  v_status text;
  v_count integer;
  v_changed boolean := false;
  v_affected integer;
begin
  if v_source is null or v_source not in ('meteofrance-climatology','meteofrance-observations')
    or p_batch->>'status' is null or p_batch->>'status' not in ('complete','partial','missing')
    or p_batch#>>'{provenance,demo}' is distinct from 'false'
    or p_batch#>>'{provenance,source_id}' is distinct from v_source
    or jsonb_typeof(p_batch->'observations') is distinct from 'array'
    or jsonb_typeof(p_stations) is distinct from 'array'
    or v_date is null or not isfinite(v_date) or v_retrieved is null
    or v_retrieved > now() + interval '5 minutes'
    or octet_length(p_batch::text) > 500000
    or p_idempotency_key is null or length(p_idempotency_key) > 200
  then raise exception 'Invalid live station batch'; end if;
  if jsonb_array_length(p_stations) not between 1 and 10
    or jsonb_array_length(p_batch->'observations') > 60
    or exists (select 1 from jsonb_array_elements(p_batch->'observations') r
      where not exists(select 1 from jsonb_array_elements(p_stations) s
        where s->>'id' = r->>'cell_id')
      or (r->>'observed_at')::timestamptz at time zone 'UTC' < v_date::timestamp
      or (r->>'observed_at')::timestamptz at time zone 'UTC' >= (v_date+1)::timestamp
      or r->>'variable' not in ('temperature','temperature_min','temperature_max',
        'precipitation','humidity','etp_monteith')
      or jsonb_typeof(r->'quality_flags') is distinct from 'array')
  then raise exception 'Invalid station coverage'; end if;
  insert into agriclimax_private.run_manifests
    (idempotency_key,status,engine_version,provenance,quality,manifest,completed_at)
  values (p_idempotency_key,'succeeded','station-ingestion-1',
    jsonb_build_array(p_batch->'provenance'),
    jsonb_build_object('batch_status',p_batch->>'status','freshness',p_batch->>'freshness'),
    p_batch - 'observations',now())
  on conflict(idempotency_key) do nothing returning id into v_run;
  if v_run is null then return false; end if;
  insert into public.sources(id,title,url,license)
  values(v_source,'Météo-France — ' || v_source,
    'https://portail-api.meteofrance.fr','Licence Ouverte Etalab 2.0')
  on conflict(id) do nothing;
  for v_station in select value from jsonb_array_elements(p_stations) loop
    if (v_station->>'latitude')::float8 not between 41 and 52
       or (v_station->>'longitude')::float8 not between -6 and 10
    then raise exception 'Station outside metropolitan MVP'; end if;
    insert into agriclimax_private.weather_stations(id,name,geom,altitude_m,metadata,retrieved_at)
    values(v_station->>'id',v_station->>'name',
      ST_SetSRID(ST_MakePoint((v_station->>'longitude')::float8,
        (v_station->>'latitude')::float8),4326),
      (v_station->>'altitude_m')::float8,v_station->'metadata',v_retrieved)
    on conflict(id) do update set name=excluded.name,geom=excluded.geom,
      altitude_m=excluded.altitude_m,metadata=excluded.metadata,retrieved_at=excluded.retrieved_at
      where excluded.retrieved_at >= agriclimax_private.weather_stations.retrieved_at;
    select coalesce(jsonb_agg(r order by r->>'observed_at',r->>'variable'),'[]'::jsonb),
      count(*) filter(where r->'value' <> 'null'::jsonb)
    into v_rows,v_count from jsonb_array_elements(p_batch->'observations') r
      where r->>'cell_id' = v_station->>'id';
    v_status := case when v_count=0 then 'missing'
      when v_count < case when v_source='meteofrance-climatology' then 6 else 3 end
        then 'partial' else 'complete' end;
    v_payload := (p_batch - 'observations' - 'status') ||
      jsonb_build_object('observations',v_rows,'status',v_status);
    insert into agriclimax_private.station_weather_batches
      (station_id,source_id,valid_date,payload,retrieved_at,run_id)
    values(v_station->>'id',v_source,v_date,v_payload,v_retrieved,v_run)
    on conflict(station_id,source_id,valid_date) do update
      set payload=excluded.payload,retrieved_at=excluded.retrieved_at,run_id=excluded.run_id
      -- An outage/partial response cannot silently erase a previously fuller batch.
      where excluded.retrieved_at >= agriclimax_private.station_weather_batches.retrieved_at
        and v_count >= (select count(*) from jsonb_array_elements(
          agriclimax_private.station_weather_batches.payload->'observations') old
          where old->'value' <> 'null'::jsonb)
        and (v_source='meteofrance-observations' or not exists (select 1 from jsonb_array_elements(
          agriclimax_private.station_weather_batches.payload->'observations') old
          where old->'value' <> 'null'::jsonb and not exists (
            select 1 from jsonb_array_elements(v_rows) incoming
            where incoming->>'variable'=old->>'variable'
              and incoming->>'observed_at'=old->>'observed_at'
              and incoming->'value' <> 'null'::jsonb)))
        and (v_source='meteofrance-climatology' or
          (select max(r->>'observed_at') from jsonb_array_elements(v_rows) r) >=
          (select max(r->>'observed_at') from jsonb_array_elements(
            agriclimax_private.station_weather_batches.payload->'observations') r));
    get diagnostics v_affected = row_count;
    v_changed := v_changed or v_affected > 0;
  end loop;
  return v_changed;
end $$;

